#!/usr/bin/env bash
# Shared helpers for scripts/ios/* — not executed directly.
#
# Ported from open-frame's scripts/ios/common.sh. What differs here: the
# Xcode project is GENERATED by XcodeGen from iosApp/project.yml and is not
# committed, so nothing in these scripts edits a .pbxproj — a setting written
# there would vanish on the next `xcodegen generate`. Settings live in
# project.yml (versions) and in the xcconfig files under iosApp/Config (team,
# AdMob ids).
#
# Source this in every ios/*.sh to get:
#   - $APP_ID                iOS bundle id (io.raylytics.justmyweather)
#   - $PROJECT_ROOT          repo root absolute path
#   - $IOS_DIR               $PROJECT_ROOT/iosApp
#   - $PROJECT_YML           $IOS_DIR/project.yml (the project's source of truth)
#   - $XCODEPROJ             $IOS_DIR/JustMyWeather.xcodeproj (generated)
#   - $CONFIG_DIR            $IOS_DIR/Config (the xcconfig files)
#   - $TEAM_XCCONFIG         $CONFIG_DIR/Team.xcconfig (gitignored; setup-team.sh)
#   - $EXPORT_OPTIONS        $IOS_DIR/ExportOptions.plist
#   - $SCHEME                JustMyWeather
#   - $BUILD_DIR             $PROJECT_ROOT/build/ios (archive + export output)
#
# Then call `load_team_properties` to populate:
#   - $IOS_TEAM_ID           Apple Developer team ID (10-char)
#   - $IOS_ASC_KEY_ID        App Store Connect API key id
#   - $IOS_ASC_ISSUER_ID     ASC API issuer id (UUID)
#   - $IOS_ASC_KEY_PATH      path to AuthKey_*.p8 (optional, altool searches conventional paths)
#
# Env vars override the properties file (CI-friendly): if a variable
# is already set in the shell, the file value is ignored.

set -euo pipefail

# Same id as Android's applicationId — unlike open-frame, the reverse-DNS name
# was free on both stores, so one id serves both (and the Maestro flows).
APP_ID="io.raylytics.justmyweather"
# Name used for the App Store provisioning profile in the Apple Developer
# Portal. export-ipa.sh pins this name in the manual-signing block of the temp
# ExportOptions; create-profile.sh creates it under the same name. If you ever
# rename the profile in the portal, update this constant in lock-step.
IOS_APP_STORE_PROFILE_NAME="Just My Weather App Store"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
IOS_DIR="$PROJECT_ROOT/iosApp"
PROJECT_YML="$IOS_DIR/project.yml"
XCODEPROJ="$IOS_DIR/JustMyWeather.xcodeproj"
CONFIG_DIR="$IOS_DIR/Config"
TEAM_XCCONFIG="$CONFIG_DIR/Team.xcconfig"
EXPORT_OPTIONS="$IOS_DIR/ExportOptions.plist"
SCHEME="JustMyWeather"
BUILD_DIR="$PROJECT_ROOT/build/ios"
TEAM_PROPERTIES="$IOS_DIR/team.properties"

export APP_ID IOS_APP_STORE_PROFILE_NAME PROJECT_ROOT IOS_DIR PROJECT_YML XCODEPROJ \
  CONFIG_DIR TEAM_XCCONFIG EXPORT_OPTIONS SCHEME BUILD_DIR

die() {
  echo "error: $1" >&2
  exit 1
}

# Read a `key=value` properties file into env vars, but only if the
# corresponding env var is not already set. Lines starting with `#`
# and blank lines are skipped. Whitespace around the `=` is trimmed.
#
# Uses bash's `printf -v` and `${!var}` indirect expansion (rather
# than eval) so values containing `$(…)` or backticks aren't
# re-evaluated as shell commands when assigned. The properties file
# holds user secrets (team ID, ASC key); we treat it as data, not code.
load_team_properties() {
  local key mapped_key value file="$TEAM_PROPERTIES"

  if [ ! -f "$file" ]; then
    if [ -z "${IOS_TEAM_ID:-}" ]; then
      die "$file not found and IOS_TEAM_ID not set in env. \
Copy iosApp/team.properties.example to iosApp/team.properties and fill in your team ID."
    fi
    return 0
  fi

  while IFS='=' read -r key value || [ -n "$key" ]; do
    # Trim whitespace
    key="${key#"${key%%[![:space:]]*}"}"
    key="${key%"${key##*[![:space:]]}"}"
    value="${value#"${value%%[![:space:]]*}"}"
    value="${value%"${value##*[![:space:]]}"}"

    # Skip comments and blanks
    case "$key" in
      ''|\#*) continue ;;
    esac

    case "$key" in
      teamID)        mapped_key="IOS_TEAM_ID" ;;
      ascKeyId)      mapped_key="IOS_ASC_KEY_ID" ;;
      ascIssuerId)   mapped_key="IOS_ASC_ISSUER_ID" ;;
      ascKeyPath)    mapped_key="IOS_ASC_KEY_PATH" ;;
      *) continue ;;  # unknown key; ignore quietly
    esac

    # Only set if not already in env (env wins for CI). `${!name}`
    # is bash indirect expansion: read the value of the variable
    # whose *name* is in $mapped_key.
    if [ -z "${!mapped_key:-}" ]; then
      printf -v "$mapped_key" '%s' "$value"
      # shellcheck disable=SC2163 # exporting the variable NAMED by mapped_key is the point
      export "$mapped_key"
    fi
  done < "$file"
}

# Validate that required vars are present after loading. Pass the var
# names to require, e.g.: require_vars IOS_TEAM_ID IOS_ASC_KEY_ID
require_vars() {
  for v in "$@"; do
    if [ -z "${!v:-}" ]; then
      die "$v is required but not set. Check $TEAM_PROPERTIES or your env."
    fi
  done
}

# Quote-aware sed for in-place edits on macOS (BSD sed needs '' after -i)
sedi() {
  if [ "$(uname)" = "Darwin" ]; then
    sed -i '' "$@"
  else
    sed -i "$@"
  fi
}

# Regenerate iosApp/JustMyWeather.xcodeproj from project.yml. Every script
# that builds calls this first: the .xcodeproj is not committed, so on a fresh
# clone it does not exist, and after a bump-build-number.sh or sync-version.sh
# edit to project.yml a stale one would build the OLD numbers.
xcodegen_generate() {
  command -v xcodegen >/dev/null 2>&1 \
    || die "xcodegen not found — the Xcode project is generated from iosApp/project.yml. Install it: brew install xcodegen"
  echo "==> xcodegen generate (iosApp/project.yml → JustMyWeather.xcodeproj)" >&2
  (cd "$IOS_DIR" && xcodegen generate --quiet) || die "xcodegen generate failed"
}

# The team id that Team.xcconfig sets, or empty. Read by archive.sh and
# install-device.sh to fail early with a named cause instead of xcodebuild's
# "Signing for JustMyWeather requires a development team" two minutes in.
read_team_xcconfig() {
  [ -f "$TEAM_XCCONFIG" ] || return 0
  sed -nE 's/^[[:space:]]*DEVELOPMENT_TEAM[[:space:]]*=[[:space:]]*([^[:space:];]*).*/\1/p' "$TEAM_XCCONFIG" | head -1
}

# Gate: the signing team is set, and set where Xcode will actually see it.
#
# Three ways it can be wrong, each checked by name:
#   1. Team.xcconfig missing / empty / placeholder — setup-team.sh never ran.
#   2. Debug/Release.xcconfig don't include it — the file exists but nothing
#      reads it.
#   3. project.yml sets DEVELOPMENT_TEAM itself. XcodeGen writes project.yml
#      `settings` into the project's build settings, and those OVERRIDE the
#      project-level xcconfig — so even `DEVELOPMENT_TEAM: ""` there silently
#      blanks the team Team.xcconfig provides.
require_team_configured() {
  local team cfg
  team="$(read_team_xcconfig)"
  if [ -z "$team" ] || [ "$team" = "REPLACE_WITH_TEAM_ID" ]; then
    die "no signing team in $TEAM_XCCONFIG. Run: scripts/ios/setup-team.sh"
  fi
  for cfg in Debug Release; do
    grep -qE '^[[:space:]]*#include\?[[:space:]]+"Team\.xcconfig"' "$CONFIG_DIR/$cfg.xcconfig" \
      || die "$CONFIG_DIR/$cfg.xcconfig does not #include? \"Team.xcconfig\". Run: scripts/ios/setup-team.sh"
  done
  if grep -qE '^[[:space:]]*DEVELOPMENT_TEAM[[:space:]]*:' "$PROJECT_YML"; then
    die "iosApp/project.yml sets DEVELOPMENT_TEAM, which overrides Team.xcconfig. Delete that line; the team lives in Team.xcconfig."
  fi
  echo "    signing team: $team" >&2
}

# ASC API key flags for xcodebuild, when team.properties has them. Lets
# xcodebuild register the bundle id's certificates/profiles through the API
# instead of failing because the local keychain hasn't seen this app yet.
# Fills the global array ASC_AUTH_ARGS (bash 3.2 has no namerefs).
ASC_AUTH_ARGS=()
asc_auth_args() {
  ASC_AUTH_ARGS=()
  if [ -n "${IOS_ASC_KEY_ID:-}" ] && [ -n "${IOS_ASC_ISSUER_ID:-}" ] && [ -n "${IOS_ASC_KEY_PATH:-}" ]; then
    ASC_AUTH_ARGS+=(
      -authenticationKeyPath "${IOS_ASC_KEY_PATH/#\~/$HOME}"
      -authenticationKeyID "$IOS_ASC_KEY_ID"
      -authenticationKeyIssuerID "$IOS_ASC_ISSUER_ID"
    )
    echo "    using ASC API key for non-interactive provisioning" >&2
  else
    echo "    no ASC API key in team.properties — relying on local Xcode keychain" >&2
  fi
}
